import {teachers,grades,subjects,getCourse,news} from './data.js';
export const portrait=(t,cls='',eager=false)=>`<img class="${cls}" src="/assets/portraits/${t.id}.webp" alt="${t.subject} ${t.name} 선생님" width="800" height="1200" loading="${eager?'eager':'lazy'}" decoding="async">`;
export const courseURL=(grade,subject='국어')=>'/courses?grade='+encodeURIComponent(grade)+'&subject='+encodeURIComponent(subject);
export const pageHeading=(label,title,desc)=>`<section class="page-heading container"><p class="eyebrow" data-reveal>${label}</p><h1 data-reveal>${title}</h1><p class="lead" data-reveal>${desc}</p></section>`;
export const newsRows=(count=3)=>`<div class="news-list">${news.slice(0,count).map(n=>`<button class="news-row" data-news="${n.id}"><span class="news-category">${n.category}</span><strong>${n.title}</strong><span class="news-date">${n.date}</span></button>`).join('')}</div>`;
export function home(){
return `<section class="intro" id="intro" aria-label="제일종합학원 강사진 스크롤 소개"><h1 class="sr-only">제일종합학원 · 너의 가능성을, 제일 높이.</h1>
<div class="intro-stage">${teachers.map((t,i)=>`<div class="teacher-scene scene-${i}" aria-hidden="${i?'true':'false'}"><div class="subject-type" aria-hidden="true">${t.subject}</div>${portrait(t,'hero-portrait',true)}<div class="teacher-caption"><p class="scene-line">${t.line.replace(', ', ',<br>')}</p><div class="teacher-identity"><span>${t.subject}</span><strong>${t.name}</strong><span>선생님</span></div></div><span class="scene-watermark" aria-hidden="true">JEIL</span></div>`).join('')}
<div class="final-scene" aria-hidden="true"><div class="ensemble">${teachers.map(t=>portrait(t,'',true)).join('')}</div><div class="final-copy"><div class="final-brand"><img src="/assets/logo.svg" width="40" height="44" alt=""><span>제일종합학원</span></div><h2>너의 가능성을,<br><span>제일 높이.</span></h2></div></div>
</div><div class="intro-bottom"><div class="scene-nav" aria-label="강사진 소개 장면 선택">${teachers.map((t,i)=>`<button data-scene="${i}" aria-label="${t.subject} 소개 장면 보기" aria-pressed="${i?'false':'true'}">${t.subject}</button>`).join('')}<button data-scene="6" aria-label="학원 브랜드 장면 보기" aria-pressed="false">제일</button></div></div></section>
<section id="home-content" class="home-overview container"><div class="section-heading" data-reveal><p class="eyebrow">같은 목표, 다른 출발점</p><h2>지금 너에게 필요한 공부.</h2><p class="lead">개념을 쌓는 시작부터 실력을 완성하는 순간까지.<br>학년별 흐름에 맞춰, 내신과 수능을 함께 준비합니다.</p></div><div class="grade-links">${grades.map((g,i)=>`<a href="${courseURL(g)}" data-route data-reveal><span>${g}</span><div><h3>${['기초를 단단하게','실력을 더 깊게','실전을 흔들림 없이'][i]}</h3><p>${['개념과 학습 습관의 시작','개념 연결과 심화 학습','실전 적용과 취약점 보완'][i]}</p></div></a>`).join('')}</div></section>
<section class="home-duo container"><a class="feature-block education-block" href="/about" data-route data-reveal><p class="eyebrow">제일의 교육</p><h2>스스로 이해하고,<br>끝내 풀어내는 힘.</h2><p>과목을 넘어, 공부의 본질을 함께 고민합니다.</p><span class="link-label">학원 소개</span><img src="/assets/logo.svg" alt="" class="feature-mark" width="80" height="88"></a><a class="feature-block learning-block" href="/learning" data-route data-reveal><p class="eyebrow">제일의 학습 관리</p><h2>수업 이후까지,<br>성장의 흐름을 잇다.</h2><div class="mini-flow"><span>진단</span><span>계획</span><span>학습</span><span>피드백</span></div><span class="link-label">학습 관리 알아보기</span></a></section>
<section class="home-teachers container"><div class="section-title-row" data-reveal><div><p class="eyebrow">한 사람의 성장을 위한 여섯 시선</p><h2>너의 다음을 여는 선생님.</h2></div><a class="text-link" href="/teachers" data-route>강사진 전체 보기</a></div><div class="teacher-strip">${teachers.map(t=>`<a href="/teachers?teacher=${t.id}" data-route data-reveal><div class="portrait-tile">${portrait(t)}</div><p><span>${t.subject}</span><strong>${t.name}</strong></p></a>`).join('')}</div></section>
<section class="home-news container"><div class="section-title-row" data-reveal><h2>제일의 새로운 이야기.</h2><a href="/news" class="text-link" data-route>소식 전체 보기</a></div>${newsRows(2)}</section>`;
}
export function about(){
return pageHeading('제일종합학원 소개','배움이 시작되고,<br><span>가능성이 커지는 곳.</span>','학생의 가능성을 키우는 제일의 교육.<br>한 학생의 오늘에서, 더 넓은 내일을 바라봅니다.')+`<section class="brand-manifesto container" data-reveal><div class="manifesto-symbol"><img src="/assets/logo.svg" alt="위로 도약하는 제일의 심볼" width="240" height="264"></div><div><p class="eyebrow">너의 가능성을, 제일 높이.</p><h2>한 과목의 자신감이<br>하루의 공부를 바꿉니다.</h2><p>제일종합학원은 국어, 영어, 수학, 사회, 과학, 한국사를 하나의 학습 흐름으로 바라보는 고등 종합학원입니다.</p><p>현재의 이해 수준을 출발점으로 삼고, 개념을 연결하는 수업과 꾸준한 학습 관리로 다음 단계를 준비하는 교육을 제안합니다.</p></div></section><section class="values-section container"><div class="section-title-row" data-reveal><h2>제일이 생각하는 공부.</h2><p>더 많은 문제보다<br>더 분명한 이해를 향해.</p></div><div class="value-row" data-reveal><h3>이해에서 시작합니다.</h3><p>정답만 확인하지 않고 풀이의 이유를 살펴봅니다. 설명할 수 있는 개념은 낯선 문제를 만나는 순간에도 힘이 됩니다.</p></div><div class="value-row" data-reveal><h3>연결하며 넓힙니다.</h3><p>단원과 단원, 개념과 사례, 수업과 복습을 연결합니다. 내신과 수능을 함께 바라보며 학습의 흐름을 만듭니다.</p></div><div class="value-row" data-reveal><h3>꾸준함을 설계합니다.</h3><p>실천할 수 있는 주간 목표와 확인 가능한 학습 기록. 작고 구체적인 피드백을 다음 공부의 출발점으로 삼습니다.</p></div></section><section class="location-note container" data-reveal><h2>대치동에서 그리는<br>배움의 새로운 장면.</h2><div><p class="eyebrow">학원 위치</p><p class="location-text">서울시 강남구 대치동</p></div></section>`;
}
export function courses(params){
const course=getCourse(params.get('grade'),params.get('subject'));
return pageHeading('학년별·과목별 교육 과정','너의 단계에 맞춰,<br><span>실력의 다음으로.</span>','학년과 과목을 선택해 학습 흐름을 살펴보세요.<br>내신과 수능을 함께 준비하는 교육 과정입니다.')+`<section class="course-explorer container" data-reveal><div class="selector-group"><p id="grade-label">학년 선택</p><div class="grade-tabs" role="group" aria-labelledby="grade-label">${grades.map(g=>`<button data-grade="${g}" aria-pressed="${g===course.grade}">${g}</button>`).join('')}</div></div><div class="selector-group"><p id="subject-label">과목 선택</p><div class="subject-tabs" role="group" aria-labelledby="subject-label">${subjects.map(s=>`<button data-subject="${s}" aria-pressed="${s===course.subject}">${s}</button>`).join('')}</div></div><div id="course-panel" aria-live="polite" aria-atomic="true">${coursePanel(course)}</div></section>`;
}
export function coursePanel(c){
return `<article class="course-detail"><div class="course-intro"><p class="eyebrow">${c.grade} · ${c.subject} · ${c.focus}</p><h2>${c.title.replace(', ', ',<br>')}</h2><p>${c.desc}</p><div class="course-teacher">${portrait(c.teacher,'',true)}<div><span>${c.subject} 강사</span><strong>${c.teacher.name} 선생님</strong><button class="text-button" data-teacher="${c.teacher.id}">강사 소개 보기</button></div></div></div><div class="course-program"><h3>${c.name}</h3><div class="program-row"><span>내신</span><p>${c.exam}</p></div><div class="program-row"><span>수능</span><p>${c.csat}</p></div><div class="program-row"><span>수업</span><p>${c.teacher.intro}</p></div><div class="course-rhythm"><span>개념 이해</span><span>문제 적용</span><span>오답 점검</span></div><button class="button button-primary" data-consult data-prefill-grade="${c.grade}" data-prefill-subject="${c.subject}">이 과정으로 학습 상담</button></div></article>`;
}
export function teacherPage(){
return pageHeading('제일의 강사진','서로 다른 전문성,<br><span>한 사람을 향한 집중.</span>','개념을 이해하는 순간부터 스스로 설명하는 순간까지.<br>여섯 과목의 선생님과 함께 학습의 다음을 찾아갑니다.')+`<section class="teacher-grid container">${teachers.map(t=>`<button class="teacher-card" data-teacher="${t.id}" data-reveal><div class="teacher-card-visual"><span class="card-subject" aria-hidden="true">${t.subject}</span>${portrait(t)}</div><div class="teacher-card-copy"><p><span>${t.subject}</span><strong>${t.name}</strong><span>선생님</span></p><h2>${t.line}</h2><span class="link-label">수업 방식 보기</span></div></button>`).join('')}</section>`;
}
export const scheduleData={
day:[['수업 전','오늘의 출발점','지난 수업의 핵심 개념을 짧게 확인하고, 오늘 해결할 질문을 적습니다.'],['수업 중','이해와 적용','개념의 연결을 살펴보고 풀이 과정을 직접 설명합니다.'],['수업 후','기억을 내 것으로','오답 원인을 정리하고 유사 문제에 다시 적용합니다.']],
week:[['주 초','이번 주의 목표','과목별 진도와 일정에 맞춰 실천 가능한 학습 목표를 정합니다.'],['주 중','학습 기록 점검','수업과 자습 기록을 확인하고 어려운 단원을 보완합니다.'],['주 말','다음 주로 이어지는 피드백','목표의 진행 상황과 오답 변화를 살펴보고 다음 계획을 조정합니다.']]
};
export const schedulePanel=key=>`<div class="schedule-list">${scheduleData[key].map(([time,title,desc])=>`<div><span>${time}</span><h3>${title}</h3><p>${desc}</p></div>`).join('')}</div>`;
export function learning(){
return pageHeading('제일의 학습 관리','좋은 수업이,<br><span>좋은 습관으로 이어지도록.</span>','배운 것을 확인하고, 부족한 부분을 찾고, 다시 계획하는 과정.<br>수업 이후의 시간까지 하나의 성장 흐름으로 연결합니다.')+`<section class="learning-system container"><div class="learning-flow" data-reveal>${[['진단','현재를 정확하게','개념 이해와 학습 습관을 살펴봅니다.'],['계획','목표를 구체적으로','학년과 과목에 맞는 주간 계획을 정합니다.'],['학습','과정을 꾸준하게','수업과 복습을 연결해 실천합니다.'],['피드백','다음을 더 분명하게','오답과 학습 기록으로 계획을 보완합니다.']].map(([name,title,desc])=>`<div><span class="flow-name">${name}</span><h2>${title}</h2><p>${desc}</p></div>`).join('')}</div></section><section class="schedule-section container" data-reveal><div class="section-title-row"><div><p class="eyebrow">학습 관리</p><h2>작은 루틴이 만드는 변화.</h2></div><div class="schedule-tabs" role="group" aria-label="학습 관리 시간 단위"><button data-schedule="day" aria-pressed="true">하루의 흐름</button><button data-schedule="week" aria-pressed="false">일주일의 흐름</button></div></div><div id="schedule-panel" aria-live="polite">${schedulePanel('day')}</div></section><section class="feedback-section container" data-reveal><h2>‘몇 개를 틀렸는지’에서<br><span>‘왜 틀렸는지’로.</span></h2><div><p>오답의 이유가 분명해지면 다음 공부도 분명해집니다. 개념 이해, 조건 해석, 풀이 과정, 시간 관리로 원인을 나눠 점검하는 방식을 제안합니다.</p><button class="button button-primary" data-consult>나의 학습 목표 선택하기</button></div></section>`;
}
export function newsPage(){
return pageHeading('제일의 소식','배움의 흐름을,<br><span>함께 나누는 이야기.</span>','교육 과정부터 학습 방법까지.<br>제일종합학원의 소식을 확인하세요.')+`<section class="news-page container" data-reveal>${newsRows()}</section>`;
}
export function teacherDetail(t){
return `<div class="teacher-modal"><div class="teacher-modal-photo">${portrait(t,'',true)}<span>${t.subject}</span></div><div class="teacher-modal-copy"><p class="eyebrow">${t.subject} 강사</p><h2>${t.name} 선생님</h2><p class="teacher-quote">“${t.quote}”</p><p>${t.intro}</p><h3>수업에서 함께 다루는 것</h3><ul class="method-list">${t.method.map(m=>`<li>${m}</li>`).join('')}</ul><a class="button button-primary" data-route href="${courseURL('고1',t.subject)}">${t.subject} 과정 살펴보기</a></div></div>`;
}


export function announcementPoster(c){
if(c.kind==='achievement')return `<article class="announcement-poster poster-achievement" aria-labelledby="announcement-heading"><div class="poster-brand"><img src="/assets/logo.svg" alt="" width="23" height="26"><span>제일종합학원</span></div><p class="poster-kicker">${c.kicker}</p><div class="achievement-headline"><h2 id="announcement-heading">${c.university}<strong>${c.achievement}</strong></h2><p class="achievement-english" aria-hidden="true">SEOUL NATIONAL UNIVERSITY</p></div><div class="achievement-student"><strong>${c.student}</strong><div><span>${c.department}</span><span>${c.grade} · 제일종합학원</span></div></div><p class="achievement-message">${c.message}</p><img class="achievement-logo" src="/assets/logo.svg" alt="" width="150" height="165"><a class="announcement-action" data-route href="${c.href}">${c.action}</a></article>`;
if(c.kind==='winter')return `<article class="announcement-poster poster-winter" aria-labelledby="announcement-heading"><div class="poster-brand"><img src="/assets/logo.svg" alt="" width="23" height="26"><span>제일종합학원</span></div><p class="poster-kicker">${c.kicker}</p><span class="winter-year" aria-hidden="true">${c.year}</span><h2 id="announcement-heading">이번 겨울,<br>너의 다음이<br><strong>달라진다.</strong></h2><img class="winter-teacher" src="/assets/portraits/math.webp" alt="수학 한서린 선생님" width="800" height="1200"><div class="winter-copy"><p>${c.audience}</p><p>${c.message}</p></div><a class="announcement-action" data-route href="${c.href}">${c.action}</a></article>`;
return `<article class="announcement-poster poster-regular" aria-labelledby="announcement-heading"><div class="poster-brand"><img src="/assets/logo.svg" alt="" width="23" height="26"><span>제일종합학원</span></div><p class="poster-kicker">${c.kicker}</p><h2 id="announcement-heading">내신도, 수능도.<br><strong>제일답게.</strong></h2><div class="regular-portraits" aria-hidden="true">${['korean','english','math'].map(id=>`<img src="/assets/portraits/${id}.webp" alt="" width="800" height="1200">`).join('')}</div><div class="regular-subjects" aria-label="운영 과목">${subjects.map(s=>`<span>${s}</span>`).join('')}</div><a class="announcement-action" data-route href="${c.href}">${c.action}</a></article>`;
}

